<template>
  <div class="commercial-page">
    <section class="commercial-hero"><div><span class="eyebrow">REPORT DELIVERY</span><h2>报告与交付</h2><p>管理授权报告、异步导出和收件人级定时订阅。</p></div><div class="commercial-stats"><span><strong>{{ reports.length }}</strong><small>报告</small></span><span><strong>{{ activeExports }}</strong><small>生成中</small></span><span><strong>{{ subscriptions.filter(item => item.status === 'ACTIVE').length }}</strong><small>有效订阅</small></span></div></section>
    <UnifiedState v-if="loading" state="loading" description="正在加载报告、订阅和成员信息。" />
    <UnifiedState v-else-if="error" state="error" :description="error" retryable @retry="load" />
    <template v-else>
      <section class="commercial-card"><header><div><span class="eyebrow">REPORT LIBRARY</span><h3>报告列表</h3></div><el-input v-model="keyword" clearable placeholder="搜索报告" style="width:260px" /></header>
        <el-table :data="filteredReports" stripe empty-text="当前企业尚无报告"><el-table-column prop="name" label="报告名称" min-width="220" /><el-table-column prop="workspaceId" label="工作空间" width="120" /><el-table-column prop="ownerMemberId" label="负责人" min-width="150"><template #default="{ row }">{{ memberName(row.ownerMemberId) }}</template></el-table-column><el-table-column prop="status" label="状态" width="110"><template #default="{ row }"><el-tag effect="plain">{{ row.status }}</el-tag></template></el-table-column><el-table-column prop="createdAt" label="创建时间" min-width="165"><template #default="{ row }">{{ formatTime(row.createdAt) }}</template></el-table-column><el-table-column label="操作" width="250" fixed="right" align="right"><template #default="{ row }"><el-button text type="primary" @click="showReport(row)">详情</el-button><el-button text type="primary" @click="openExport(row)">导出</el-button><el-button text type="primary" @click="openSubscription(row)">订阅</el-button></template></el-table-column></el-table>
      </section>
      <section class="commercial-card"><header><div><span class="eyebrow">ASYNC EXPORTS</span><h3>本次会话导出任务</h3></div><span class="commercial-hint">只有服务端返回 SUCCEEDED 后才能下载</span></header>
        <el-table :data="exports" empty-text="本次会话尚未创建导出任务"><el-table-column prop="id" label="任务 ID" width="110" /><el-table-column prop="reportId" label="报告" min-width="170"><template #default="{ row }">{{ reportName(row.reportId) }}</template></el-table-column><el-table-column prop="format" label="格式" width="90" /><el-table-column label="状态" min-width="190"><template #default="{ row }"><el-tag :type="exportStatus(row.status, row.errorCode).type">{{ exportStatus(row.status, row.errorCode).label }}</el-tag></template></el-table-column><el-table-column prop="expiresAt" label="文件有效期" min-width="170"><template #default="{ row }">{{ row.expiresAt ? formatTime(row.expiresAt) : '生成后确定' }}</template></el-table-column><el-table-column label="操作" width="180" align="right"><template #default="{ row }"><el-button v-if="row.status === 'SUCCEEDED'" text type="primary" @click="download(row)">下载</el-button><el-button v-if="shouldPollExport(row)" text type="danger" @click="cancelExport(row)">取消</el-button></template></el-table-column></el-table>
      </section>
      <section class="commercial-card"><header><div><span class="eyebrow">SCHEDULED DELIVERY</span><h3>定时报告订阅</h3></div></header>
        <el-table :data="subscriptions" empty-text="尚未创建定时订阅"><el-table-column prop="reportId" label="报告" min-width="180"><template #default="{ row }">{{ reportName(row.reportId) }}</template></el-table-column><el-table-column prop="schedule" label="调度表达式" min-width="160" /><el-table-column prop="timezone" label="时区" width="150" /><el-table-column label="收件成员" min-width="220"><template #default="{ row }">{{ row.recipientMemberIds.map(memberName).join('、') }}</template></el-table-column><el-table-column prop="nextRunAt" label="下次运行" min-width="170"><template #default="{ row }">{{ formatTime(row.nextRunAt) }}</template></el-table-column><el-table-column label="状态/操作" width="180"><template #default="{ row }"><el-tag :type="row.status === 'ACTIVE' ? 'success' : 'info'">{{ row.status }}</el-tag><el-button v-if="row.creatorMemberId === app.currentMember?.id" text type="primary" @click="toggleSubscription(row)">{{ row.status === 'ACTIVE' ? '暂停' : '启用' }}</el-button></template></el-table-column></el-table>
      </section>
    </template>

    <el-drawer v-model="detailOpen" title="报告详情" size="68%"><template v-if="selectedReport"><div class="commercial-detail-heading"><div><h3>{{ selectedReport.name }}</h3><p>报告 ID {{ selectedReport.id }} · {{ selectedReport.rows.length }} 行 · {{ selectedReport.columns.length }} 列</p></div><el-tag>{{ selectedReport.status }}</el-tag></div><el-alert type="info" title="报告内容由服务端按当前成员权限返回，前端仅渲染当前分页。" :closable="false" show-icon /><el-table :data="reportPageRows" stripe max-height="560" style="margin-top:16px"><el-table-column v-for="column in selectedReport.columns" :key="column" :prop="column" :label="column" min-width="140" /></el-table><CommonPagination v-model:page="reportPage" v-model:page-size="reportPageSize" :total="reportTotal" /></template></el-drawer>
    <CommonDialog v-model="exportOpen" title="创建异步导出" width="480px"><el-form label-position="top"><el-form-item label="报告"><el-input :model-value="selectedReport?.name" disabled /></el-form-item><el-form-item label="文件格式"><el-radio-group v-model="exportFormat"><el-radio-button value="CSV">CSV</el-radio-button><el-radio-button value="XLSX">Excel</el-radio-button><el-radio-button value="PDF">PDF</el-radio-button></el-radio-group></el-form-item></el-form><el-alert title="提交仅表示任务已创建，不代表导出成功。" type="warning" :closable="false" /><template #footer><el-button @click="exportOpen=false">取消</el-button><el-button type="primary" :loading="exporting" @click="createExport">提交任务</el-button></template></CommonDialog>
    <CommonDialog v-model="subscriptionOpen" title="创建定时报告订阅" width="600px"><el-form label-position="top"><el-form-item label="报告"><el-input :model-value="selectedReport?.name" disabled /></el-form-item><div class="commercial-form-grid"><el-form-item label="调度"><el-select v-model="subscriptionForm.schedule"><el-option label="每天 09:00" value="0 0 9 * * *" /><el-option label="每周一 09:00" value="0 0 9 * * MON" /><el-option label="每月 1 日 09:00" value="0 0 9 1 * *" /></el-select></el-form-item><el-form-item label="时区"><el-input v-model="subscriptionForm.timezone" /></el-form-item></div><el-form-item label="收件成员"><el-select v-model="subscriptionForm.recipientMemberIds" multiple filterable style="width:100%"><el-option v-for="member in activeMembers" :key="member.id" :label="member.memberName" :value="member.id" /></el-select></el-form-item></el-form><el-alert title="每次投递前服务端会重新检查收件人状态与权限。" type="info" :closable="false" /><template #footer><el-button @click="subscriptionOpen=false">取消</el-button><el-button type="primary" :loading="savingSubscription" :disabled="!subscriptionForm.recipientMemberIds.length" @click="createSubscription">创建订阅</el-button></template></CommonDialog>
  </div>
</template>

<script setup lang="ts">
import type { Id } from '../api/resource-id'
import { resourceId } from '../api/resource-id'
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { ElMessage } from 'element-plus'
import CommonDialog from '../components/common/CommonDialog.vue'
import CommonPagination from '../components/common/CommonPagination.vue'
import UnifiedState from '../components/common/UnifiedState.vue'
import { commercialApi, organizationApi } from '../api/runtime'
import { exportStatus, shouldPollExport } from '../commercial/presentation'
import type { ExportTask, Report, ReportSubscription } from '../commercial/types'
import type { MemberContext } from '../auth/types'
import { useAppStore } from '../stores/app'
import { useClientPagination } from '../composables/useClientPagination'
import { useConfirm } from '../composables/useConfirm'

const app = useAppStore(); const reports = ref<Report[]>([]); const subscriptions = ref<ReportSubscription[]>([]); const exports = ref<ExportTask[]>([]); const members = ref<MemberContext[]>([])
const { confirm } = useConfirm()
const loading = ref(true); const error = ref(''); const keyword = ref(''); const selectedReport = ref<Report>(); const detailOpen = ref(false); const exportOpen = ref(false); const exporting = ref(false); const exportFormat = ref<ExportTask['format']>('CSV'); const subscriptionOpen = ref(false); const savingSubscription = ref(false)
const subscriptionForm = ref({ schedule: '0 0 9 * * MON', timezone: 'Asia/Shanghai', recipientMemberIds: [] as Id[] }); let pollTimer: ReturnType<typeof setTimeout> | undefined
const filteredReports = computed(() => reports.value.filter(item => item.name.toLowerCase().includes(keyword.value.toLowerCase()))); const activeMembers = computed(() => members.value.filter(item => item.memberStatus === 'ACTIVE')); const activeExports = computed(() => exports.value.filter(shouldPollExport).length)
const reportRows = computed(() => selectedReport.value?.rows.map(row => Object.fromEntries(selectedReport.value!.columns.map((column, index) => [column, row[index] ?? '']))) ?? [])
const { page: reportPage, pageSize: reportPageSize, total: reportTotal, pageRows: reportPageRows } = useClientPagination(reportRows)
async function load() { loading.value=true; error.value=''; try { [reports.value, subscriptions.value, members.value] = await Promise.all([commercialApi.reports(), commercialApi.subscriptions(), organizationApi.members(resourceId(app.tenantId))]); schedulePoll() } catch(e){ error.value=e instanceof Error?e.message:'报告数据加载失败' } finally { loading.value=false } }
async function showReport(report: Report) { try { selectedReport.value=await commercialApi.report(report.id); detailOpen.value=true } catch(e){ ElMessage.error(e instanceof Error?e.message:'报告详情加载失败') } }
function openExport(report: Report){ selectedReport.value=report; exportFormat.value='CSV'; exportOpen.value=true }
async function createExport(){ if(!selectedReport.value||exporting.value)return; exporting.value=true; try{ const task=await commercialApi.createExport(selectedReport.value.id,exportFormat.value); exports.value.unshift(task); exportOpen.value=false; schedulePoll(); ElMessage.success('导出任务已提交，正在等待服务端生成') }catch(e){ ElMessage.error(e instanceof Error?e.message:'导出任务创建失败') }finally{exporting.value=false} }
function schedulePoll(){ if(pollTimer)clearTimeout(pollTimer); if(!exports.value.some(shouldPollExport))return; pollTimer=setTimeout(()=>void refreshExports(),1500) }
async function refreshExports(){ const pending=exports.value.filter(shouldPollExport); const updates=await Promise.allSettled(pending.map(item=>commercialApi.exportTask(item.id))); updates.forEach((result,index)=>{if(result.status==='fulfilled'){const at=exports.value.findIndex(item=>item.id===pending[index]?.id);if(at>=0)exports.value[at]=result.value}}); schedulePoll() }
async function cancelExport(task:ExportTask){ if(!await confirm(`取消导出任务 #${task.id} 后，已生成的临时结果将不可下载。`,{title:'取消导出',confirmText:'确认取消',danger:true}))return; const next=await commercialApi.cancelExport(task.id); exports.value[exports.value.findIndex(item=>item.id===task.id)]=next }
async function download(task:ExportTask){ const file=await commercialApi.downloadExport(task.id); const url=URL.createObjectURL(file.blob); const anchor=document.createElement('a'); anchor.href=url; anchor.download=file.fileName; anchor.click(); URL.revokeObjectURL(url) }
function openSubscription(report:Report){ selectedReport.value=report; subscriptionForm.value={schedule:'0 0 9 * * MON',timezone:'Asia/Shanghai',recipientMemberIds:[]}; subscriptionOpen.value=true }
async function createSubscription(){if(!selectedReport.value)return;savingSubscription.value=true;try{const created=await commercialApi.createSubscription({reportId:selectedReport.value.id,...subscriptionForm.value});subscriptions.value.push(created);subscriptionOpen.value=false;ElMessage.success('定时订阅已创建')}finally{savingSubscription.value=false}}
async function toggleSubscription(item:ReportSubscription){const next=item.status==='ACTIVE'?'PAUSED':'ACTIVE';if(!await confirm(`${next==='PAUSED'?'暂停':'启用'}订阅后，${next==='PAUSED'?'后续计划投递将停止':'服务端将在下次运行前重新校验收件人权限'}。`,{title:`${next==='PAUSED'?'暂停':'启用'}报告订阅`,confirmText:'确认'}))return;const updated=await commercialApi.updateSubscription(item.id,{status:next});subscriptions.value[subscriptions.value.findIndex(row=>row.id===item.id)]=updated}
function memberName(id:Id){return members.value.find(item=>item.id===id)?.memberName??`成员 ${id}`} function reportName(id:Id){return reports.value.find(item=>item.id===id)?.name??`报告 ${id}`} function formatTime(value:string){return new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value))}
watch(()=>app.contextVersion,()=>void load()); onBeforeUnmount(()=>{if(pollTimer)clearTimeout(pollTimer)}); void load()
</script>
